def solution(text: str) -> str:
    """Applies ROT13 to the input text, shifting letters by 13 positions."""
    result = []
    for ch in text:
        o = ord(ch)
        if 'a' <= ch <= 'z':
            result.append(chr((o - ord('a') + 13) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            result.append(chr((o - ord('A') + 13) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)
